const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const B = nextInt();
const edges = new Array(B);

for (let i = 0; i < B; i++) {
  edges[i] = { u: nextInt(), v: nextInt(), w: nextInt() };
}

const C = nextInt();
const queryX = new Int32Array(C);
const queryY = new Int32Array(C);
for (let i = 0; i < C; i++) {
  queryX[i] = nextInt();
  queryY[i] = nextInt();
}

edges.sort((a, b) => b.w - a.w);

const dsuParent = new Int32Array(N + 1);
const dsuSize = new Int32Array(N + 1);
for (let i = 1; i <= N; i++) {
  dsuParent[i] = i;
  dsuSize[i] = 1;
}

function find(x) {
  let root = x;
  while (dsuParent[root] !== root) root = dsuParent[root];
  while (dsuParent[x] !== x) {
    const parent = dsuParent[x];
    dsuParent[x] = root;
    x = parent;
  }
  return root;
}

const head = new Int32Array(N + 1);
head.fill(-1);
const to = new Int32Array(2 * N);
const next = new Int32Array(2 * N);
const weight = new Int32Array(2 * N);
let edgeCount = 0;

function addEdge(u, v, w) {
  to[edgeCount] = v;
  weight[edgeCount] = w;
  next[edgeCount] = head[u];
  head[u] = edgeCount++;
}

let selected = 0;
for (const edge of edges) {
  let ru = find(edge.u);
  let rv = find(edge.v);
  if (ru !== rv) {
    if (dsuSize[ru] < dsuSize[rv]) {
      const tmp = ru;
      ru = rv;
      rv = tmp;
    }
    dsuParent[rv] = ru;
    dsuSize[ru] += dsuSize[rv];

    addEdge(edge.u, edge.v, edge.w);
    addEdge(edge.v, edge.u, edge.w);
    if (++selected === N - 1) break;
  }
}

const levels = Math.ceil(Math.log2(N)) + 1;
const up = new Array(levels);
const minEdge = new Array(levels);
for (let k = 0; k < levels; k++) {
  up[k] = new Int32Array(N + 1);
  minEdge[k] = new Int32Array(N + 1);
}

const depth = new Int32Array(N + 1);
const stack = new Int32Array(N);
let stackSize = 0;
stack[stackSize++] = 1;
up[0][1] = 1;
minEdge[0][1] = 1_000_000_000;

while (stackSize > 0) {
  const u = stack[--stackSize];
  for (let e = head[u]; e !== -1; e = next[e]) {
    const v = to[e];
    if (v === up[0][u]) continue;
    up[0][v] = u;
    minEdge[0][v] = weight[e];
    depth[v] = depth[u] + 1;
    stack[stackSize++] = v;
  }
}

for (let k = 1; k < levels; k++) {
  const prevUp = up[k - 1];
  const currUp = up[k];
  const prevMin = minEdge[k - 1];
  const currMin = minEdge[k];

  for (let v = 1; v <= N; v++) {
    const middle = prevUp[v];
    currUp[v] = prevUp[middle];
    currMin[v] = Math.min(prevMin[v], prevMin[middle]);
  }
}

const output = new Array(C);

for (let i = 0; i < C; i++) {
  let a = queryX[i];
  let b = queryY[i];
  let answer = 1_000_000_000;

  if (depth[a] < depth[b]) {
    const tmp = a;
    a = b;
    b = tmp;
  }

  let diff = depth[a] - depth[b];
  for (let k = 0; diff > 0; k++, diff >>= 1) {
    if (diff & 1) {
      answer = Math.min(answer, minEdge[k][a]);
      a = up[k][a];
    }
  }

  if (a !== b) {
    for (let k = levels - 1; k >= 0; k--) {
      if (up[k][a] !== up[k][b]) {
        answer = Math.min(answer, minEdge[k][a], minEdge[k][b]);
        a = up[k][a];
        b = up[k][b];
      }
    }
    answer = Math.min(answer, minEdge[0][a], minEdge[0][b]);
  }

  output[i] = String(answer);
}

console.log(output.join('\n'));
